from AlgorithmImports import *
import math


class Lot:
    """A strategy's private lot of shares in its trade ticker."""

    def __init__(self, symbol):
        self.symbol = symbol
        self.shares = 0

    @property
    def is_empty(self):
        return self.shares == 0


class TwoSlotParallelAlgorithm(QCAlgorithm):

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    SMA_PERIOD = 50
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # --- Indicators / rolling state -------------------------------------
        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, self.RSI_PERIOD,
                                 MovingAverageType.Wilders, Resolution.Daily)

        # previous-day values used for cross / red-day detection
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        # --- Slots ----------------------------------------------------------
        self.lot_a = Lot(self.spy)    # Slot 1 - Strategy A
        self.lot_b = Lot(self.aapl)   # Slot 2 - Strategy B

        self.SetWarmUp(max(self.SMA_PERIOD, self.RSI_PERIOD) + 1, Resolution.Daily)

    # ------------------------------------------------------------------ utils
    def _all_bars_present(self, data):
        for symbol in self.symbols.values():
            bar = data.Bars.get(symbol)
            if bar is None:
                return False
        return True

    def _buy_shares(self, lot, quantity):
        if quantity <= 0:
            return
        self.MarketOrder(lot.symbol, quantity)
        lot.shares += quantity

    def _sell_shares(self, lot, quantity):
        quantity = min(quantity, lot.shares)
        if quantity <= 0:
            return
        self.MarketOrder(lot.symbol, -quantity)
        lot.shares -= quantity

    def _liquidate_lot(self, lot):
        if lot.shares > 0:
            self._sell_shares(lot, lot.shares)

    # ------------------------------------------------------------------- main
    def OnData(self, data):
        if not self._all_bars_present(data):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --- market-state quantities, always computed continuously ----------
        prev_spy_close = self.prev_spy_close
        prev_spy_sma = self.prev_spy_sma
        prev_aapl_close = self.prev_aapl_close

        spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        aapl_rsi = self.aapl_rsi.Current.Value if self.aapl_rsi.IsReady else None

        if prev_aapl_close is not None:
            if aapl_close < prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # store today's values for tomorrow's comparisons
        self.prev_spy_close = spy_close
        self.prev_spy_sma = spy_sma
        self.prev_aapl_close = aapl_close

        if self.IsWarmingUp:
            return
        if spy_sma is None or aapl_rsi is None:
            return
        if prev_spy_close is None or prev_spy_sma is None or prev_aapl_close is None:
            return

        crossed_above = prev_spy_close <= prev_spy_sma and spy_close > spy_sma
        crossed_below = prev_spy_close >= prev_spy_sma and spy_close < spy_sma

        # ================= Slot 1 - Strategy A (SPY) ========================
        # sells before buys
        if not self.lot_a.is_empty:
            if crossed_below:
                self._liquidate_lot(self.lot_a)
        else:
            if crossed_above:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = int(target_value / spy_close)
                self._buy_shares(self.lot_a, quantity)

        # ================= Slot 2 - Strategy B (AAPL) =======================
        if not self.lot_b.is_empty:
            if aapl_rsi > 60:
                self._liquidate_lot(self.lot_b)
        else:
            if self.aapl_red_streak >= 3:
                budget = 20000.0
                if self.Portfolio.Cash >= budget:
                    quantity = int(math.floor(budget / aapl_close))
                    self._buy_shares(self.lot_b, quantity)

