from AlgorithmImports import *


class ParallelTwoSlotAlgorithm(QCAlgorithm):

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for t in self.TICKERS:
            eq = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = eq.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators (registered so they update continuously from data)
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Previous-day cached values for cross detection
        self.prev_spy_close = None
        self.prev_sma100 = None
        self.prev_rsi = None

        # Previous close per ticker for red/green streaks
        self.prev_close = {t: None for t in self.TICKERS}
        self.red_streak = {t: 0 for t in self.TICKERS}

        # Private lots (shares owned by each strategy)
        self.lot_a = 0
        self.lot_b = 0

        self.SetWarmUp(120, Resolution.Daily)

    # ------------------------------------------------------------------
    def _bar_for_all(self, data):
        """Return dict of TradeBars if every subscribed ticker has today's bar."""
        bars = {}
        for t in self.TICKERS:
            sym = self.symbols[t]
            if not data.ContainsKey(sym):
                return None
            bar = data[sym]
            if bar is None:
                return None
            bars[t] = bar
        return bars

    def OnData(self, data):
        bars = self._bar_for_all(data)
        if bars is None:
            return

        # --- Always update market-state quantities from data ---
        for t in self.TICKERS:
            close = bars[t].Close
            prev = self.prev_close[t]
            if prev is not None:
                if close < prev:
                    self.red_streak[t] += 1
                else:
                    self.red_streak[t] = 0

        spy_close = bars["SPY"].Close
        sma_now = self.sma100.Current.Value if self.sma100.IsReady else None
        rsi_now = self.rsi14.Current.Value if self.rsi14.IsReady else None

        prev_spy_close = self.prev_spy_close
        prev_sma = self.prev_sma100
        prev_rsi = self.prev_rsi

        # Cache today's values for tomorrow, regardless of trading eligibility
        self.prev_spy_close = spy_close
        self.prev_sma100 = sma_now
        self.prev_rsi = rsi_now
        for t in self.TICKERS:
            self.prev_close[t] = bars[t].Close

        # --- Gate on warmup / indicator readiness ---
        if self.IsWarmingUp:
            return
        if not (self.sma100.IsReady and self.rsi14.IsReady):
            return
        if prev_spy_close is None or prev_sma is None or prev_rsi is None:
            return

        # ============ Slot 1 - Strategy A (SPY) ============
        # Sell before buy
        if self.lot_a > 0:
            if prev_spy_close >= prev_sma and spy_close < sma_now:
                self.MarketOrder(self.spy, -self.lot_a)
                self.lot_a = 0

        if self.lot_a == 0:
            if prev_spy_close <= prev_sma and spy_close > sma_now:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                qty = int(target_value / spy_close)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)
                    self.lot_a = qty

        # ============ Slot 2 - Strategy B (AAPL) ============
        aapl_close = bars["AAPL"].Close

        if self.lot_b > 0:
            if rsi_now > 60:
                self.MarketOrder(self.aapl, -self.lot_b)
                self.lot_b = 0

        if self.lot_b == 0:
            if self.red_streak["AAPL"] >= 3:
                if self.Portfolio.Cash >= 20000:
                    qty = int(20000 / aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.lot_b = qty

